/** ҳаста_қимат 안의 연결형 байт_қимат ҷараён_қимат. Ethernet/TCP 패킷 스택이 아닌 루프백 socket леер_қимат. */
public final class ҷараён_Шабака {
    static int[] вазъият_қимат = new int[16], порт_қимат = new int[16], 짝 = new int[16], ҳамсон_порт = new int[16], 대기 = new int[16], 묶임 = new int[16];
    static int[] 앞 = new int[16], 수 = new int[16], иттилоот = new int[16 * 1024];
    static int 다음 = 50000;
    static int тасдиқ_кардан(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && вазъият_қимат[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int 접속번호) { for (int ҳалқа_индекс = 0; ҳалқа_индекс < 16; ҳалқа_индекс++) if (вазъият_қимат[ҳалқа_индекс] != 0 && 묶임[ҳалқа_индекс] != 0 && порт_қимат[ҳалқа_индекс] == 접속번호) return true; return false; }
    public static int эҷод_кардан_ворида() {
        for (int ҳалқа_индекс = 0; ҳалқа_индекс < 16; ҳалқа_индекс++) if (вазъият_қимат[ҳалқа_индекс] == 0) { вазъият_қимат[ҳалқа_индекс] = 1; ҳамсон_порт[ҳалқа_индекс] = порт_қимат[ҳалқа_индекс] = 앞[ҳалқа_индекс] = 수[ҳалқа_индекс] = 대기[ҳалқа_индекс] = 묶임[ҳалқа_индекс] = 0; 짝[ҳалқа_индекс] = -1; return ҳалқа_индекс + 40; }
        return -24;
    }
    public static int 묶기(int 열린파일번호, int 통신주소, int 접속번호) {
        int ҳалқа_индекс = тасдиқ_кардан(열린파일번호); if (ҳалқа_индекс < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (вазъият_қимат[ҳалқа_индекс] != 1 || 접속번호 < 0 || 접속번호 > 65535) return -22;
        if (접속번호 == 0) { do { 접속번호 = 다음++; if (다음 > 65535) 다음 = 50000; } while (사용중(접속번호)); }
        if (사용중(접속번호)) return -98; порт_қимат[ҳалқа_индекс] = 접속번호; 묶임[ҳалқа_индекс] = 1; вазъият_қимат[ҳалқа_индекс] = 2; return 0;
    }
    public static int 듣기(int 열린파일번호, int 연결대기한도) { int ҳалқа_индекс = тасдиқ_кардан(열린파일번호); if (ҳалқа_индекс < 0) return -9; if (вазъият_қимат[ҳалқа_индекс] != 2 || 연결대기한도 < 1) return -22; вазъият_қимат[ҳалқа_индекс] = 3; return 0; }
    public static int ПАЙВАСТ(int 열린파일번호, int 통신주소, int 접속번호) {
        int ҳалқа_индекс = тасдиқ_кардан(열린파일번호); if (ҳалқа_индекс < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (접속번호 < 1 || 접속번호 > 65535 || вазъият_қимат[ҳалқа_индекс] > 2) return -22;
        int 수신쪽 = -1; for (int 안쪽자리 = 0; 안쪽자리 < 16; 안쪽자리++) if (вазъият_қимат[안쪽자리] == 3 && порт_қимат[안쪽자리] == 접속번호) 수신쪽 = 안쪽자리;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int 안쪽자리 = 0; 안쪽자리 < 16; 안쪽자리++) if (대기[안쪽자리] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (вазъият_қимат[ҳалқа_индекс] == 1) { int 처리값 = 묶기(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = эҷод_кардан_ворида(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        вазъият_қимат[ҳалқа_индекс] = вазъият_қимат[다른번호] = 4; 짝[ҳалқа_индекс] = 다른번호; 짝[다른번호] = ҳалқа_индекс; порт_қимат[다른번호] = 접속번호; ҳамсон_порт[ҳалқа_индекс] = 접속번호; ҳамсон_порт[다른번호] = порт_қимат[ҳалқа_индекс]; 대기[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int қабул_кардан_пайваст(int 열린파일번호) { int ҳалқа_индекс = тасдиқ_кардан(열린파일번호); if (ҳалқа_индекс < 0) return -9; if (вазъият_қимат[ҳалқа_индекс] != 3) return -22; for (int 안쪽자리 = 0; 안쪽자리 < 16; 안쪽자리++) if (вазъият_қимат[안쪽자리] != 0 && 대기[안쪽자리] == ҳалқа_индекс + 1) { 대기[안쪽자리] = 0; return 안쪽자리 + 40; } return -11; }
    public static int Навиштан(int 열린파일번호, int 항목수) {
        int ҳалқа_индекс = тасдиқ_кардан(열린파일번호); if (ҳалқа_индекс < 0) return -9; if (вазъият_қимат[ҳалқа_индекс] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int 안쪽자리 = 짝[ҳалқа_индекс]; if (안쪽자리 < 0) return -32; int 총수 = 1024 - 수[안쪽자리]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int 비교자리 = 0; 비교자리 < 총수; 비교자리++) иттилоот[안쪽자리 * 1024 + (앞[안쪽자리] + 수[안쪽자리] + 비교자리) % 1024] = 되돌림망.бозфиристодан_қимат[비교자리]; 수[안쪽자리] += 총수; return 총수;
    }
    public static int Хондан(int 열린파일번호, int 항목수) {
        int ҳалқа_индекс = тасдиқ_кардан(열린파일번호); if (ҳалқа_индекс < 0) return -9; if (вазъият_қимат[ҳалқа_индекс] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[ҳалқа_индекс] == 0) return 짝[ҳалқа_индекс] < 0 ? 0 : -11; if (항목수 > 수[ҳалқа_индекс]) 항목수 = 수[ҳалқа_индекс];
        for (int 비교자리 = 0; 비교자리 < 항목수; 비교자리++) 되돌림망.бозфиристодан_қимат[비교자리] = иттилоот[ҳалқа_индекс * 1024 + (앞[ҳалқа_индекс] + 비교자리) % 1024]; 앞[ҳалқа_индекс] = (앞[ҳалқа_индекс] + 항목수) % 1024; 수[ҳалқа_индекс] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int ҳалқа_индекс = тасдиқ_кардан(열린파일번호); return ҳалқа_индекс < 0 ? -9 : порт_қимат[ҳалқа_индекс]; }
    public static int 상대창구읽기(int 열린파일번호) { int ҳалқа_индекс = тасдиқ_кардан(열린파일번호); return ҳалқа_индекс < 0 ? -9 : ҳамсон_порт[ҳалқа_индекс]; }
    public static int Пӯшидан(int 열린파일번호) {
        int ҳалқа_индекс = тасдиқ_кардан(열린파일번호); if (ҳалқа_индекс < 0) return -9;
        if (вазъият_қимат[ҳалқа_индекс] == 3) for (int 안쪽자리 = 0; 안쪽자리 < 16; 안쪽자리++) if (대기[안쪽자리] == ҳалқа_индекс + 1) { if (짝[안쪽자리] >= 0) 짝[짝[안쪽자리]] = -1; вазъият_қимат[안쪽자리] = 대기[안쪽자리] = 묶임[안쪽자리] = 0; }
        if (짝[ҳалқа_индекс] >= 0) 짝[짝[ҳалқа_индекс]] = -1; вазъият_қимат[ҳалқа_индекс] = 묶임[ҳалқа_индекс] = 수[ҳалқа_индекс] = 대기[ҳалқа_индекс] = 0; return 0;
    }
}
